import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { Fn, uv, color, mix, sin, dot, fract, vec2 } from 'three/tsl';
import gsap from 'gsap';
import { createMSDFText } from '@/text';

// Design-token scale: scene-unit em-height per px, derived so that
// 18px -> 0.09u (caption), 26px -> 0.13u (body), 124px -> 0.62u (hero).
const PX_TO_UNITS = 0.005;
const pxu = (px) => px * PX_TO_UNITS;

function disposeObject3D(obj) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      // Do NOT dispose child.material.map / uniform textures here —
      // MSDF atlas + shared textures are cache-owned by ctx.fontAtlas /
      // ctx.textureLoader and may be reused by sibling nodes.
      child.material.dispose();
    }
  });
}

function setOpacity(obj, value) {
  if (!obj) return;
  obj.traverse((child) => {
    if (child.material) {
      child.material.transparent = true;
      child.material.opacity = value;
    }
  });
}

export default function createNode(config, ctx) {
  const colors = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    ...(config.visual && config.visual.colors ? config.visual.colors : {}),
  };

  const scenePos = config.scenePosition || {};
  const posX = scenePos.x ?? 0;
  const posY = scenePos.y ?? 0;
  const posZ = scenePos.z ?? 0;
  const rot = scenePos.rotationXYZ || { x: 0, y: 0, z: 0 };
  const scl = scenePos.scaleXYZ || { x: 1, y: 1, z: 1 };

  const group = new Group();
  group.name = 'nova-atelier-editorial-headline';
  group.position.set(posX, posY, posZ);
  group.rotation.set(rot.x || 0, rot.y || 0, rot.z || 0);
  group.scale.set(scl.x || 1, scl.y || 1, scl.z || 1);
  group.userData.handlers = {};

  const disposables = [];

  // ---------------------------------------------------------------------
  // Full-bleed backdrop plate: 7 x 5.5 units, vertical engineered gradient
  // + 1.5% monochrome grain (no soft blur — hard procedural noise).
  // ---------------------------------------------------------------------
  const PLATE_W = 7;
  const PLATE_H = 5.5;
  const PLATE_CENTER_Y = -0.25; // matches hub-frame bounds y[-3,2.5]

  const grainNode = Fn(() => {
    const p = uv().mul(1024.0);
    const n = fract(sin(dot(p, vec2(12.9898, 78.233))).mul(43758.5453));
    return n.sub(0.5).mul(0.03); // +-1.5%
  })();

  const plateGeometry = new PlaneGeometry(PLATE_W, PLATE_H);
  const plateMaterial = new MeshBasicNodeMaterial();
  plateMaterial.colorNode = mix(
    color(colors.background),
    color(colors.surface),
    uv().y
  ).add(grainNode);
  disposables.push(plateGeometry, plateMaterial);

  const plateMesh = new Mesh(plateGeometry, plateMaterial);
  plateMesh.position.set(0, PLATE_CENTER_Y, -0.01);
  plateMesh.name = 'editorial-plate';
  group.add(plateMesh);

  // ---------------------------------------------------------------------
  // Text content — pull from config.textContent by role, fall back to
  // the authored spec strings.
  // ---------------------------------------------------------------------
  const textContent = Array.isArray(config.textContent) ? config.textContent : [];
  const byRole = (role) => textContent.filter((t) => t && t.role === role);

  const kickerEntry = byRole('kicker')[0] || { text: 'NOVA ATELIER / JOURNAL' };
  const heroEntries = byRole('hero');
  const heroLine1 = heroEntries[0] || { text: 'PRECISION IS' };
  const heroLine2 = heroEntries[1] || { text: 'A HABIT.' };
  const bodyEntry = byRole('body')[0] || {
    text: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
  };
  const captionEntry = byRole('caption')[0] || { text: 'ISSUE 12 / JULY 2026' };

  const typography = (config.visual && config.visual.typography) || {};

  // ---------------------------------------------------------------------
  // Kicker
  // ---------------------------------------------------------------------
  const kickerMesh = createMSDFText(ctx.fontAtlas, {
    text: kickerEntry.text,
    fontFamily: 'JetBrains Mono',
    fontWeight: (typography.kicker && typography.kicker.fontWeight) || 700,
    fontSize: pxu((typography.kicker && typography.kicker.fontSize) || 18),
    letterSpacing: (typography.kicker && typography.kicker.letterSpacing) ?? 0.12,
    lineHeight: (typography.kicker && typography.kicker.lineHeight) || 1.4,
    color: colors.paper,
    align: 'left',
  });
  const kickerGroup = new Group();
  kickerGroup.add(kickerMesh);
  kickerGroup.position.set(-3.1, 1.7, 0);
  group.add(kickerGroup);

  // ---------------------------------------------------------------------
  // Hero — two stacked lines, each with a letterpress-shadow duplicate
  // offset 0.02 units behind in ink color.
  // ---------------------------------------------------------------------
  function buildHeroLine(entry, y) {
    const heroFontSize = pxu((typography.hero && typography.hero.fontSize) || 124);
    const heroTracking = (typography.hero && typography.hero.letterSpacing) ?? -0.015;
    const heroLineHeight = (typography.hero && typography.hero.lineHeight) || 0.98;

    const shadowMesh = createMSDFText(ctx.fontAtlas, {
      text: entry.text,
      fontFamily: 'Lora',
      fontWeight: (typography.hero && typography.hero.fontWeight) || 600,
      fontSize: heroFontSize,
      letterSpacing: heroTracking,
      lineHeight: heroLineHeight,
      color: colors.ink,
      align: 'left',
    });
    shadowMesh.position.set(0, 0, -0.02);

    const mainMesh = createMSDFText(ctx.fontAtlas, {
      text: entry.text,
      fontFamily: 'Lora',
      fontWeight: (typography.hero && typography.hero.fontWeight) || 600,
      fontSize: heroFontSize,
      letterSpacing: heroTracking,
      lineHeight: heroLineHeight,
      color: colors.paper,
      align: 'left',
    });
    mainMesh.position.set(0, 0, 0);

    const lineGroup = new Group();
    lineGroup.add(shadowMesh);
    lineGroup.add(mainMesh);
    lineGroup.position.set(-3.1, y, 0);
    return lineGroup;
  }

  const heroGroup1 = buildHeroLine(heroLine1, 0.9);
  const heroGroup2 = buildHeroLine(heroLine2, 0.25);
  group.add(heroGroup1);
  group.add(heroGroup2);

  // ---------------------------------------------------------------------
  // Accent underline rule — 2.2 x 0.05 units, pivoted at its left edge so
  // it can be scaled in from x=0 -> 1 like a drawn stroke.
  // ---------------------------------------------------------------------
  const RULE_W = 2.2;
  const RULE_H = 0.05;
  const ruleGeometry = new PlaneGeometry(RULE_W, RULE_H);
  ruleGeometry.translate(RULE_W / 2, 0, 0);
  const ruleMaterial = new MeshBasicNodeMaterial();
  ruleMaterial.colorNode = color(colors.accent).mul(1.2);
  disposables.push(ruleGeometry, ruleMaterial);

  const ruleMesh = new Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(-3.1, -0.15, 0.001);
  ruleMesh.scale.x = 0;
  ruleMesh.name = 'accent-underline-rule';
  group.add(ruleMesh);

  // ---------------------------------------------------------------------
  // Body
  // ---------------------------------------------------------------------
  const bodyMesh = createMSDFText(ctx.fontAtlas, {
    text: bodyEntry.text,
    fontFamily: 'JetBrains Mono',
    fontWeight: (typography.body && typography.body.fontWeight) || 400,
    fontSize: pxu((typography.body && typography.body.fontSize) || 26),
    letterSpacing: (typography.body && typography.body.letterSpacing) ?? 0,
    lineHeight: (typography.body && typography.body.lineHeight) || 1.55,
    color: colors.paper,
    align: 'left',
    maxWidth: 4.5,
  });
  const bodyGroup = new Group();
  bodyGroup.add(bodyMesh);
  bodyGroup.position.set(-3.1, -0.8, 0);
  group.add(bodyGroup);

  // ---------------------------------------------------------------------
  // Caption
  // ---------------------------------------------------------------------
  const captionMesh = createMSDFText(ctx.fontAtlas, {
    text: captionEntry.text,
    fontFamily: 'JetBrains Mono',
    fontWeight: (typography.caption && typography.caption.fontWeight) || 400,
    fontSize: pxu((typography.caption && typography.caption.fontSize) || 18),
    letterSpacing: (typography.caption && typography.caption.letterSpacing) ?? 0.08,
    lineHeight: (typography.caption && typography.caption.lineHeight) || 1.4,
    color: colors.paper,
    align: 'left',
  });
  const captionGroup = new Group();
  captionGroup.add(captionMesh);
  captionGroup.position.set(-3.1, -1.9, 0);
  group.add(captionGroup);

  // ---------------------------------------------------------------------
  // Cinematic primitives — applied generically per config (none listed
  // for this node, but the loop honors the contract regardless).
  // ---------------------------------------------------------------------
  const primitiveRefs = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  primitiveRefs.forEach((primitive) => {
    const fn = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof fn === 'function') {
      fn(group, primitive.params);
    }
  });

  // ---------------------------------------------------------------------
  // Entrance animation: rise-in per block, top-to-bottom, 80ms stagger,
  // then the accent rule draws in scaleX after the hero has landed.
  // ---------------------------------------------------------------------
  const RISE_OFFSET = 0.4;
  const RISE_DURATION = 0.7;
  const RISE_STAGGER = 0.08;
  const orderedBlocks = [kickerGroup, heroGroup1, heroGroup2, bodyGroup, captionGroup];

  const tl = gsap.timeline();

  orderedBlocks.forEach((block, i) => {
    const finalY = block.position.y;
    block.position.y = finalY + RISE_OFFSET;
    setOpacity(block, 0);
    const startTime = i * RISE_STAGGER;

    tl.to(
      block.position,
      { y: finalY, duration: RISE_DURATION, ease: 'power3.out' },
      startTime
    );

    const opacityTarget = { value: 0 };
    tl.to(
      opacityTarget,
      {
        value: 1,
        duration: RISE_DURATION,
        ease: 'power3.out',
        onUpdate: () => setOpacity(block, opacityTarget.value),
      },
      startTime
    );
  });

  const heroLandTime = 1 * RISE_STAGGER + RISE_DURATION; // heroGroup1's slot
  tl.to(
    ruleMesh.scale,
    { x: 1, duration: 0.5, ease: 'power2.out' },
    heroLandTime
  );

  // ---------------------------------------------------------------------
  // Cleanup
  // ---------------------------------------------------------------------
  group.userData.cleanup = () => {
    tl.kill();
    disposables.forEach((res) => {
      if (res && typeof res.dispose === 'function') res.dispose();
    });
    disposeObject3D(kickerGroup);
    disposeObject3D(heroGroup1);
    disposeObject3D(heroGroup2);
    disposeObject3D(bodyGroup);
    disposeObject3D(captionGroup);
    if (plateMesh.geometry) plateMesh.geometry.dispose();
    if (plateMesh.material) plateMesh.material.dispose();
    if (ruleMesh.geometry) ruleMesh.geometry.dispose();
    if (ruleMesh.material) ruleMesh.material.dispose();
  };

  return group;
}
